UPDATE ADMIN_MST
SET LAST_CNTN_DT = NOW()
WHERE ID = #{id}

mapper.select:
SELECT Q.CNTN_QSTN_SN, Q.CNTN_SN, Q.QSTN_TYPE_CD, CASE Q.QSTN_TYPE_CD WHEN 'SELECT' THEN '선택형 활동' WHEN 'DATA' THEN '데이터 입력' WHEN 'PHOTO' THEN '사진 업로드' WHEN 'SENTENCE' THEN '문장완성형' ELSE Q.QSTN_TYPE_CD END AS QSTN_TYPE_NM, Q.QSTN_NM, Q.QSTN_IMG_ATCH_FILE_ID, Q.OPTN_CN, Q.SORT_SEQ FROM EDU_CNTN_QSTN Q WHERE Q.CNTN_SN IN
#{contentId}
ORDER BY Q.CNTN_SN ASC, Q.SORT_SEQ ASC, Q.CNTN_QSTN_SN ASC

